import re
from dataclasses import dataclass, field
from typing import Optional

# Release headings: "## [2.4.0] - 2024-05-02". The date is absent for "## [Unreleased]".
HEADING = re.compile(
    r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\d{4}-\d{2}-\d{2}))?\s*$"
)

# Maintainer comments, inline or spanning lines. Any spaces or tabs before the
# comment go with it, and so do trailing spaces when the comment ends its line.
COMMENT = re.compile(r"[ \t]*<!--.*?-->(?:[ \t]*(?=\r?\n|\Z))?", re.DOTALL)


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def strip_comments(text):
    return COMMENT.sub("", text)


def parse_changelog(text):
    releases = []
    current = None
    for line in strip_comments(text).splitlines():
        match = HEADING.match(line) if line.startswith("## ") else None
        if match:
            current = Release(match.group("version"), match.group("date"))
            releases.append(current)
        elif current is not None:
            current.body.append(line)
    return releases


def _clean_body(lines):
    out = []
    for line in lines:
        if line.strip() == "":
            if out and out[-1] != "":
                out.append("")
        else:
            out.append(line)
    while out and out[-1] == "":
        out.pop()
    return "\n".join(out)


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            title = f"# {release.version}"
            if release.date:
                title += f" ({release.date})"
            body = _clean_body(release.body)
            return f"{title}\n\n{body}\n"
    raise LookupError(version)
EOF
